using Aspose.Cells;

// // Creates a workbook, turns on gridlines for printed output, sets the print quality to 600 DPI via PageSetup, and saves the file as output.xlsx.
class Program
{
    static void Main()
    {
        // Create a new workbook (or load an existing one)
        Workbook workbook = new Workbook();

        // Access the first worksheet
        Worksheet sheet = workbook.Worksheets[0];

        // Enable gridlines in the printed output
        sheet.PageSetup.PrintGridlines = true;

        // Set high print quality (e.g., 600 DPI)
        sheet.PageSetup.PrintQuality = 600;

        // Save the workbook to a file
        workbook.Save("output.xlsx");
    }
}
